DO $$ BEGIN CREATE TYPE public.corporate_decision AS ENUM ('allow','requires_approval','block'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.corporate_invitation_status AS ENUM ('pending','accepted','revoked','expired'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.designation_limit_period AS ENUM ('weekly','fortnightly','monthly'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.expense_code_level AS ENUM ('CORPORATE','GROUP','EMPLOYEE'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.legal_status AS ENUM ('not_applicable','unknown','review_required','evidence_required','submitted', 'under_review','verified','active','expiring','expired','suspended','revoked'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.paybill_proof_status AS ENUM ('pending','approved','rejected'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS public.charter_document_registry ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), control_number text NOT NULL UNIQUE, fingerprint text NOT NULL, template_version text NOT NULL, document_kind text NOT NULL DEFAULT 'receipt', reference text NOT NULL, booking_id uuid REFERENCES public.charter_bookings(id) ON DELETE SET NULL, file_name text, amount_kes numeric, issued_by uuid, issued_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.charter_idempotency_keys ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), idempotency_key text NOT NULL, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, action text NOT NULL, request_hash text NOT NULL, response jsonb, status text NOT NULL DEFAULT 'completed', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (user_id, action, idempotency_key) );
CREATE TABLE IF NOT EXISTS public.charter_notification_prefs ( user_id UUID NOT NULL PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, contact_email TEXT, quote_emails BOOLEAN NOT NULL DEFAULT true, booking_emails BOOLEAN NOT NULL DEFAULT true, status_emails BOOLEAN NOT NULL DEFAULT true, downloadable_summaries BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.charter_partner_application_events ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, application_id UUID NOT NULL REFERENCES public.charter_partner_applications(id) ON DELETE CASCADE, actor_id UUID, actor_email TEXT, action TEXT NOT NULL, from_status TEXT, to_status TEXT, note TEXT, document_path TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.charter_pdf_templates ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version text NOT NULL UNIQUE, label text NOT NULL, active boolean NOT NULL DEFAULT false, brand jsonb NOT NULL DEFAULT '{}'::jsonb, layout jsonb NOT NULL DEFAULT '{}'::jsonb, notes text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.charter_rfq_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quote_id uuid NOT NULL REFERENCES public.charter_quotes(id) ON DELETE CASCADE, state_from text, state_to text NOT NULL, reason text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.charter_webhook_endpoints ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), label text NOT NULL, url text NOT NULL, secret text NOT NULL DEFAULT encode(gen_random_bytes(24), 'hex'), events text[] NOT NULL DEFAULT ARRAY['charter.cabin_changed','charter.seats_changed','charter.gallery_selected','charter.ground_package_changed'], active boolean NOT NULL DEFAULT true, description text, last_status text, last_delivered_at timestamptz, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.client_journey_events ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), correlation_id UUID NOT NULL, user_id UUID, session_id TEXT, event_key TEXT NOT NULL, route TEXT, component TEXT, target_function TEXT, http_status INTEGER, duration_ms INTEGER, success BOOLEAN, error_message TEXT, evidence JSONB NOT NULL DEFAULT '{}', occurred_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.client_portal_grants ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES public.crm_accounts(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, recipient_email text, recipient_name text, expires_at timestamptz NOT NULL, revoked_at timestamptz, first_opened_at timestamptz, last_opened_at timestamptz, opens integer NOT NULL DEFAULT 0, created_by uuid, created_staff_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.client_portal_preferences ( user_id uuid PRIMARY KEY, company_name text, preferred_contact text NOT NULL DEFAULT 'email' CHECK (preferred_contact IN ('email','phone','whatsapp')), email_updates boolean NOT NULL DEFAULT true, sms_updates boolean NOT NULL DEFAULT false, marketing_updates boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.contract_documents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract_id uuid NOT NULL REFERENCES public.commercial_contract_instances(id) ON DELETE CASCADE, document_type text NOT NULL CHECK (document_type = ANY (ARRAY[ 'draft','final','executed','acceptance_evidence','signature_evidence','amendment','addendum','supporting'])), version integer NOT NULL DEFAULT 1, storage_bucket text NOT NULL DEFAULT 'crm-documents', storage_path text, file_name text, external_reference text, status text NOT NULL DEFAULT 'current' CHECK (status = ANY (ARRAY['current','superseded','void'])), source text NOT NULL DEFAULT 'upload', notes text, uploaded_by uuid, uploaded_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (contract_id, document_type, version) );
CREATE TABLE IF NOT EXISTS public.contract_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract_id uuid NOT NULL REFERENCES public.commercial_contract_instances(id) ON DELETE CASCADE, event_type text NOT NULL, from_status text, to_status text, before_state jsonb NOT NULL DEFAULT '{}'::jsonb, after_state jsonb NOT NULL DEFAULT '{}'::jsonb, reason text, source text NOT NULL DEFAULT 'staff_ui', actor_id uuid, actor_staff_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.contract_portal_invites ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract_id uuid NOT NULL REFERENCES public.commercial_contract_instances(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, recipient_email text, recipient_name text, expires_at timestamptz NOT NULL DEFAULT (now() + interval '30 days'), opened_at timestamptz, completed_at timestamptz, revoked_at timestamptz, created_by uuid, created_staff_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.contract_revenue_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract_id uuid NOT NULL REFERENCES public.commercial_contract_instances(id) ON DELETE CASCADE, account_id uuid NOT NULL REFERENCES public.crm_accounts(id) ON DELETE CASCADE, opportunity_id uuid REFERENCES public.commercial_opportunities(id) ON DELETE SET NULL, lead_id uuid, staff_member_id uuid, event_type text NOT NULL DEFAULT 'CONTRACT_EXECUTED' CHECK (event_type = ANY (ARRAY['CONTRACT_EXECUTED','CONTRACT_AMENDED','CONTRACT_TERMINATED','MANUAL_ADJUSTMENT'])), activation_version integer NOT NULL DEFAULT 1, amount numeric(14,2) NOT NULL CHECK (amount <> 0), currency text NOT NULL DEFAULT 'KES' CHECK (currency ~ '^[A-Z]{3}$'), value_type text NOT NULL DEFAULT 'one_time', execution_date date NOT NULL, revenue_period text NOT NULL CHECK (revenue_period ~ '^\d{4}-\d{2}$'), revenue_treatment text NOT NULL DEFAULT 'contracted', source text NOT NULL DEFAULT 'contract_activation', reason text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (contract_id, event_type, activation_version) );
CREATE TABLE IF NOT EXISTS public.corporate_admin_permission_grants ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, role text NOT NULL, capability text NOT NULL, allowed boolean NOT NULL DEFAULT false, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (role, capability) );
CREATE TABLE IF NOT EXISTS public.corporate_admin_sessions ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, admin_user_id uuid NOT NULL, corporate_id uuid NOT NULL, reason text, correlation_id text, started_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now() + interval '30 minutes'), ended_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_bank_guarantee_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), guarantee_id uuid NOT NULL REFERENCES public.corporate_bank_guarantees(id) ON DELETE RESTRICT, corporate_id uuid NOT NULL, event_type text NOT NULL, state_before public.bank_guarantee_state, state_after public.bank_guarantee_state, actor_id uuid, actor_role text, reason text, before_snapshot jsonb, after_snapshot jsonb, correlation_id uuid, source text NOT NULL DEFAULT 'rpc', created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_designations ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id UUID NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, department_id UUID REFERENCES public.corporate_departments(id) ON DELETE SET NULL, title TEXT NOT NULL, expense_limit_cents BIGINT NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'KES', limit_period public.designation_limit_period NOT NULL DEFAULT 'monthly', active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (corporate_id, department_id, title) );
CREATE TABLE IF NOT EXISTS public.corporate_document_audit_log ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, corporate_id UUID NOT NULL, document_id UUID, doc_type TEXT, action TEXT NOT NULL, actor_id UUID, actor_role TEXT, from_status TEXT, to_status TEXT, reason TEXT, detail JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_document_notification_prefs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, user_id uuid NOT NULL, in_app boolean NOT NULL DEFAULT true, email boolean NOT NULL DEFAULT true, expiry_window_days integer NOT NULL DEFAULT 30 CHECK (expiry_window_days BETWEEN 1 AND 365), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (corporate_id, user_id) );
CREATE TABLE IF NOT EXISTS public.corporate_document_notifications ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, corporate_id UUID NOT NULL, document_id UUID, doc_type TEXT, kind TEXT NOT NULL, severity TEXT NOT NULL DEFAULT 'info', title TEXT NOT NULL, body TEXT, expiry_date DATE, dedupe_key TEXT NOT NULL, read_at TIMESTAMPTZ, email_sent_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (corporate_id, dedupe_key) );
CREATE TABLE IF NOT EXISTS public.corporate_document_versions ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, document_id UUID NOT NULL, corporate_id UUID NOT NULL, doc_type TEXT NOT NULL, document_number TEXT, expiry_date DATE, storage_path TEXT NOT NULL, original_name TEXT NOT NULL, mime TEXT NOT NULL, size_bytes BIGINT NOT NULL, status TEXT NOT NULL, reviewer_notes TEXT, reviewed_by UUID, reviewed_at TIMESTAMPTZ, uploaded_by UUID, version_number INT NOT NULL DEFAULT 1, reason TEXT, snapshotted_by UUID, snapshotted_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_documents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, doc_type text NOT NULL, document_number text, expiry_date date, storage_path text NOT NULL, original_name text NOT NULL, mime text NOT NULL, size_bytes bigint NOT NULL, status text NOT NULL DEFAULT 'pending', reviewer_notes text, uploaded_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, reviewed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, reviewed_at timestamptz, uploaded_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT corporate_documents_status_chk CHECK (status IN ('pending','approved','rejected')), CONSTRAINT corporate_documents_doc_type_chk CHECK (doc_type IN ( 'business_photo','certificate_of_incorporation','contract', 'cr12','crb_payment','crb_report','kra_pin','tax_compliance' )), CONSTRAINT corporate_documents_corp_type_uk UNIQUE (corporate_id, doc_type) );
CREATE TABLE IF NOT EXISTS public.corporate_employee_approvers ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id UUID NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, employee_id UUID NOT NULL REFERENCES public.corporate_employees(id) ON DELETE CASCADE, approver_user_id UUID NOT NULL, order_index INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (employee_id, approver_user_id) );
CREATE TABLE IF NOT EXISTS public.corporate_expense_code_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, expense_code text NOT NULL, action text NOT NULL, level public.expense_code_level, created_for text, actor_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, ip_address text, payload jsonb, result text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_expense_codes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, expense_code text NOT NULL, description text, start_time timestamptz, end_time timestamptz, ride_cap integer CHECK (ride_cap IS NULL OR ride_cap > 0), rides_used integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (corporate_id, expense_code) );
CREATE TABLE IF NOT EXISTS public.corporate_invitations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, department_id uuid REFERENCES public.corporate_departments(id) ON DELETE SET NULL, email text NOT NULL, full_name text, role public.corporate_employee_role NOT NULL DEFAULT 'corporate_employee', token text NOT NULL UNIQUE DEFAULT encode(gen_random_bytes(24), 'hex'), status public.corporate_invitation_status NOT NULL DEFAULT 'pending', invited_by uuid, expires_at timestamptz NOT NULL DEFAULT (now() + interval '14 days'), accepted_at timestamptz, accepted_by uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_kyb_audit_log ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), action TEXT NOT NULL, actor_kind TEXT NOT NULL, actor_id UUID, actor_session_key TEXT, draft_id UUID, document_id UUID, notification_id UUID, outcome TEXT NOT NULL, detail JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_kyb_rescan_cooldowns ( scope TEXT NOT NULL, key TEXT NOT NULL, last_run_at TIMESTAMPTZ NOT NULL DEFAULT now(), run_count_1m INT NOT NULL DEFAULT 1, window_started_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (scope, key) );
CREATE TABLE IF NOT EXISTS public.corporate_ops_alert_rules ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, name text NOT NULL, signal text NOT NULL, operator text NOT NULL DEFAULT 'gte', threshold numeric NOT NULL DEFAULT 1, severity text NOT NULL DEFAULT 'warning', enabled boolean NOT NULL DEFAULT true, channels text[] NOT NULL DEFAULT ARRAY['toast']::text[], target_roles text[] NOT NULL DEFAULT ARRAY['super_admin']::text[], cooldown_seconds integer NOT NULL DEFAULT 900, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_paybill_proofs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, mpesa_code text NOT NULL, amount_cents bigint NOT NULL CHECK (amount_cents > 0), currency text NOT NULL DEFAULT 'KES', payer_phone text, paid_at timestamptz, proof_file_path text, paybill_reference text NOT NULL, status public.paybill_proof_status NOT NULL DEFAULT 'pending', submitted_by uuid, reviewed_by uuid, reviewed_at timestamptz, review_notes text, ledger_entry_id uuid REFERENCES public.corporate_cash_ledger(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_policy_audit_log ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, actor_user_id uuid, action text NOT NULL, target_type text, target_id uuid, before jsonb, after jsonb, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_policy_violations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, employee_id uuid REFERENCES public.corporate_employees(id) ON DELETE SET NULL, user_id uuid, policy_id uuid REFERENCES public.corporate_ride_policies(id) ON DELETE SET NULL, rule_id uuid REFERENCES public.corporate_policy_rules(id) ON DELETE SET NULL, decision public.corporate_decision NOT NULL, reason text NOT NULL, ride_type text, fare_cents bigint, distance_km numeric, context jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_registration_drafts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_key text UNIQUE NOT NULL, user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','submitted','abandoned')), current_step int NOT NULL DEFAULT 1 CHECK (current_step BETWEEN 1 AND 5), completed_steps int[] NOT NULL DEFAULT '{}'::int[], business_registration_type text CHECK (business_registration_type IN ('limited_company','registered_business')), personal_info jsonb NOT NULL DEFAULT '{}'::jsonb, business_info jsonb NOT NULL DEFAULT '{}'::jsonb, documents jsonb NOT NULL DEFAULT '{}'::jsonb, submitted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_registration_rescan_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, scanned_count integer NOT NULL DEFAULT 0, changed_count integer NOT NULL DEFAULT 0, newly_failed_count integer NOT NULL DEFAULT 0, detail jsonb NOT NULL DEFAULT '{}'::jsonb );
CREATE TABLE IF NOT EXISTS public.corporate_role_audit_log ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, corporate_id UUID NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, employee_id UUID NOT NULL REFERENCES public.corporate_employees(id) ON DELETE CASCADE, changed_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, changed_by_email TEXT, previous_role TEXT, new_role TEXT NOT NULL, reason TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_support_tickets ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, corporate_id uuid NOT NULL, subject text NOT NULL, category text NOT NULL DEFAULT 'general', severity text NOT NULL DEFAULT 'medium', status text NOT NULL DEFAULT 'open', booking_ref text, opened_by uuid, assigned_to uuid, last_activity_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.legal_contracts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract_code text NOT NULL, version text NOT NULL DEFAULT '1.0', title text NOT NULL, contract_type text NOT NULL, counterparty_type text NOT NULL DEFAULT 'customer', counterparty_id uuid, counterparty_name text, scope text, territory text, services text[] NOT NULL DEFAULT '{}', commercial_terms jsonb NOT NULL DEFAULT '{}'::jsonb, obligations_summary text, document_path text, signed_at timestamptz, effective_from date, effective_until date, auto_renew boolean NOT NULL DEFAULT false, owner_user_id uuid, status public.legal_status NOT NULL DEFAULT 'review_required', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (contract_code, version) );
CREATE TABLE IF NOT EXISTS public.rec_application_contract ( id boolean PRIMARY KEY DEFAULT true CHECK (id), api_contract_version integer NOT NULL DEFAULT 1, application_schema_version integer NOT NULL DEFAULT 1, minimum_supported_client_version integer NOT NULL DEFAULT 1, requirement_schema_version integer NOT NULL DEFAULT 1, careers_build_id text, notes text, updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rental_corporate_accounts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_code text NOT NULL UNIQUE, legal_name text NOT NULL, match_names text[] NOT NULL DEFAULT '{}', corporate_id uuid, cost_centre text, status text NOT NULL DEFAULT 'PENDING_ONBOARDING' CHECK (status IN ('PENDING_ONBOARDING','ACTIVE','CREDIT_BLOCKED','SUSPENDED')), credit_state text NOT NULL DEFAULT 'NO_CREDIT' CHECK (credit_state IN ('NO_CREDIT','APPLIED','APPROVED','BLOCKED')), credit_limit_kes numeric(14,2) NOT NULL DEFAULT 0, payment_terms_days integer NOT NULL DEFAULT 0, auto_approve_below_kes numeric(14,2), elevated_approval_above_kes numeric(14,2), approver_name text, approver_email text, note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.charter_webhook_deliveries ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), endpoint_id uuid REFERENCES public.charter_webhook_endpoints(id) ON DELETE CASCADE, event_type text NOT NULL, event_id text NOT NULL, booking_id uuid, reference text, actor_user_id uuid, payload jsonb NOT NULL DEFAULT '{}'::jsonb, attempts integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'pending', response_status integer, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.contract_amendments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), contract_id uuid NOT NULL REFERENCES public.commercial_contract_instances(id) ON DELETE CASCADE, amendment_no int NOT NULL, amendment_type text NOT NULL CHECK (amendment_type IN ('value','term_dates','commercial_terms','scope','mixed')), reason text NOT NULL, effective_date date, value_before numeric, value_after numeric, value_delta numeric, currency text NOT NULL DEFAULT 'KES', revenue_period text, revenue_event_id uuid REFERENCES public.contract_revenue_events(id), before_state jsonb NOT NULL, after_state jsonb NOT NULL, changed_fields text[] NOT NULL DEFAULT '{}'::text[], actor_id uuid, actor_staff_id uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (contract_id, amendment_no) );
CREATE TABLE IF NOT EXISTS public.corporate_admin_actions ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, admin_user_id uuid NOT NULL, corporate_id uuid, session_id uuid REFERENCES public.corporate_admin_sessions(id) ON DELETE SET NULL, action text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, result text NOT NULL DEFAULT 'applied', error_reason text, correlation_id text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_expense_code_scopes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, expense_code_id uuid NOT NULL REFERENCES public.corporate_expense_codes(id) ON DELETE CASCADE, level public.expense_code_level NOT NULL, department_id uuid REFERENCES public.corporate_departments(id) ON DELETE CASCADE, employee_id uuid REFERENCES public.corporate_employees(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (expense_code_id, level, department_id, employee_id), CHECK ( (level = 'CORPORATE' AND department_id IS NULL AND employee_id IS NULL) OR (level = 'GROUP' AND department_id IS NOT NULL AND employee_id IS NULL) OR (level = 'EMPLOYEE' AND employee_id IS NOT NULL AND department_id IS NULL) ) );
CREATE TABLE IF NOT EXISTS public.corporate_ops_alert_events ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, rule_id uuid REFERENCES public.corporate_ops_alert_rules(id) ON DELETE SET NULL, rule_name text NOT NULL, signal text NOT NULL, severity text NOT NULL DEFAULT 'warning', corporate_id uuid, observed_value numeric, threshold numeric, message text NOT NULL, context jsonb NOT NULL DEFAULT '{}'::jsonb, acknowledged_by uuid, acknowledged_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_registration_conflict_log ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), draft_id uuid REFERENCES public.corporate_registration_drafts(id) ON DELETE SET NULL, session_key text, user_id uuid, op text NOT NULL, reason text NOT NULL DEFAULT 'already_submitted', correlation_id text, request_ip text, user_agent text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_registration_documents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), draft_id uuid NOT NULL REFERENCES public.corporate_registration_drafts(id) ON DELETE CASCADE, session_key text NOT NULL, slot_key text NOT NULL, storage_path text NOT NULL, original_name text NOT NULL, mime text NOT NULL, size_bytes bigint NOT NULL, scan_status text NOT NULL DEFAULT 'pending' CHECK (scan_status IN ('pending','clean','infected','error')), scan_result jsonb NOT NULL DEFAULT '{}'::jsonb, ocr_text text, extracted jsonb NOT NULL DEFAULT '{}'::jsonb, validation jsonb NOT NULL DEFAULT '{}'::jsonb, admin_decision text CHECK (admin_decision IN ('approved','rejected')), admin_reason text, admin_reviewer uuid REFERENCES auth.users(id) ON DELETE SET NULL, admin_reviewed_at timestamptz, uploaded_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (draft_id, slot_key) );
CREATE TABLE IF NOT EXISTS public.corporate_support_ticket_notes ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, ticket_id uuid NOT NULL REFERENCES public.corporate_support_tickets(id) ON DELETE CASCADE, author_user_id uuid, author_email text, body text NOT NULL, is_internal boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rental_corporate_approvals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES public.rental_corporate_accounts(id) ON DELETE CASCADE, quote_id uuid REFERENCES public.rental_quote_requests(id) ON DELETE SET NULL, quote_reference text, booking_reference text, amount_kes numeric(14,2) NOT NULL, required_level text NOT NULL DEFAULT 'DESIGNATED_APPROVER' CHECK (required_level IN ('AUTO_APPROVED','DESIGNATED_APPROVER','ELEVATED_APPROVAL')), state text NOT NULL DEFAULT 'REQUESTED' CHECK (state IN ('REQUESTED','APPROVED','REJECTED','WITHDRAWN')), policy_code text, policy_version integer, reason text, decided_by uuid, decided_at timestamptz, decision_note text, correlation_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rental_corporate_budgets ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES public.rental_corporate_accounts(id) ON DELETE CASCADE, period_month date NOT NULL, budget_kes numeric(14,2) NOT NULL CHECK (budget_kes >= 0), note text, set_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (account_id, period_month) );
CREATE TABLE IF NOT EXISTS public.contract_amendment_billing ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), amendment_id uuid NOT NULL UNIQUE REFERENCES public.contract_amendments(id) ON DELETE CASCADE, contract_id uuid NOT NULL REFERENCES public.commercial_contract_instances(id) ON DELETE CASCADE, invoice_id uuid REFERENCES public.tax_invoices(id) ON DELETE SET NULL, work_item_id uuid, amount_cents bigint NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', status text NOT NULL DEFAULT 'invoice_raised', created_by uuid, created_staff_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_registration_reviews ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), draft_id uuid NOT NULL REFERENCES public.corporate_registration_drafts(id) ON DELETE CASCADE, document_id uuid REFERENCES public.corporate_registration_documents(id) ON DELETE CASCADE, reviewer_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, scope text NOT NULL CHECK (scope IN ('document','draft')), decision text NOT NULL CHECK (decision IN ('approved','rejected','requested_changes')), reason text, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_registration_document_versions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES public.corporate_registration_documents(id) ON DELETE CASCADE, draft_id uuid NOT NULL REFERENCES public.corporate_registration_drafts(id) ON DELETE CASCADE, slot_key text NOT NULL, version integer NOT NULL, storage_path text NOT NULL, original_name text NOT NULL, mime text NOT NULL, size_bytes bigint NOT NULL, scan_status text NOT NULL DEFAULT 'pending', scan_result jsonb NOT NULL DEFAULT '{}'::jsonb, extracted jsonb NOT NULL DEFAULT '{}'::jsonb, ocr_confidence jsonb NOT NULL DEFAULT '{}'::jsonb, validation jsonb NOT NULL DEFAULT '{}'::jsonb, admin_decision text CHECK (admin_decision IN ('approved','rejected')), admin_reason text, admin_reviewer uuid REFERENCES auth.users(id) ON DELETE SET NULL, admin_reviewed_at timestamptz, review_id uuid REFERENCES public.corporate_registration_reviews(id) ON DELETE SET NULL, superseded_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (document_id, version) );
CREATE TABLE IF NOT EXISTS public.corporate_registration_notifications ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), draft_id uuid NOT NULL REFERENCES public.corporate_registration_drafts(id) ON DELETE CASCADE, session_key text NOT NULL, kind text NOT NULL CHECK (kind IN ( 'draft_approved','draft_rejected','draft_changes_requested', 'document_approved','document_rejected','rescan_failed' )), title text NOT NULL, message text, reason text, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, review_id uuid REFERENCES public.corporate_registration_reviews(id) ON DELETE SET NULL, document_id uuid REFERENCES public.corporate_registration_documents(id) ON DELETE SET NULL, slot_key text, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
ALTER TABLE public.charter_document_registry ADD COLUMN IF NOT EXISTS signature text, ADD COLUMN IF NOT EXISTS qr_payload text, ADD COLUMN IF NOT EXISTS validation_token text, ADD COLUMN IF NOT EXISTS token_consumed_at timestamptz, ADD COLUMN IF NOT EXISTS procurement jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS audit_chain jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.corporate_registration_drafts ADD COLUMN IF NOT EXISTS validation jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS submitted_at timestamptz, ADD COLUMN IF NOT EXISTS decision text CHECK (decision IN ('pending','approved','rejected','changes_requested')), ADD COLUMN IF NOT EXISTS decided_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS decided_at timestamptz, ADD COLUMN IF NOT EXISTS decision_reason text;
ALTER TABLE public.corporate_registration_documents ADD COLUMN IF NOT EXISTS current_version integer NOT NULL DEFAULT 1, ADD COLUMN IF NOT EXISTS ocr_confidence jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS ocr_provider text, ADD COLUMN IF NOT EXISTS last_scanned_at timestamptz, ADD COLUMN IF NOT EXISTS last_rescan_run_id uuid REFERENCES public.corporate_registration_rescan_runs(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS reupload_required boolean NOT NULL DEFAULT false;
ALTER TABLE public.corporate_registration_reviews ADD COLUMN IF NOT EXISTS document_version_id uuid REFERENCES public.corporate_registration_document_versions(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS correlation_id uuid;
ALTER TABLE public.corporate_registration_notifications ADD COLUMN IF NOT EXISTS ack_attempts INT NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS ack_last_error TEXT, ADD COLUMN IF NOT EXISTS ack_last_attempt_at TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS ack_next_retry_at TIMESTAMPTZ;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['charter_document_registry','charter_idempotency_keys','charter_notification_prefs','charter_partner_application_events','charter_pdf_templates','charter_rfq_events','charter_webhook_endpoints','client_journey_events','client_portal_grants','client_portal_preferences','contract_documents','contract_events','contract_portal_invites','contract_revenue_events','corporate_admin_permission_grants','corporate_admin_sessions','corporate_bank_guarantee_events','corporate_designations','corporate_document_audit_log','corporate_document_notification_prefs','corporate_document_notifications','corporate_document_versions','corporate_documents','corporate_employee_approvers','corporate_expense_code_audit','corporate_expense_codes','corporate_invitations','corporate_kyb_audit_log','corporate_kyb_rescan_cooldowns','corporate_ops_alert_rules','corporate_paybill_proofs','corporate_policy_audit_log','corporate_policy_violations','corporate_registration_drafts','corporate_registration_rescan_runs','corporate_role_audit_log','corporate_support_tickets','legal_contracts','rec_application_contract','rental_corporate_accounts','charter_webhook_deliveries','contract_amendments','corporate_admin_actions','corporate_expense_code_scopes','corporate_ops_alert_events','corporate_registration_conflict_log','corporate_registration_documents','corporate_support_ticket_notes','rental_corporate_approvals','rental_corporate_budgets','contract_amendment_billing','corporate_registration_reviews','corporate_registration_document_versions','corporate_registration_notifications'] LOOP EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t); EXECUTE format('GRANT ALL ON public.%I TO service_role', t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('CREATE POLICY "Admins manage restored records" ON public.%I FOR ALL TO authenticated USING (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'',''corporate_admin'']::public.app_role[])) WITH CHECK (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'',''corporate_admin'']::public.app_role[]))', t); END LOOP; END $$;
